void UpdateRef(ref int x) { x += 10; }
void AssignOut(out int y) { y = 42; } // must be set before return

int a = 5;
UpdateRef(ref a);      // a is now 15

int b;                 // no need to initialize
AssignOut(out b);      // b is now 42

int number = 123;
object boxed = number;        // boxing: heap allocation
int unboxed = (int)boxed;     // unboxing: must cast back to the exact value type

public abstract class Animal
{
    public string Name { get; set; }
    public abstract string MakeSound();
}

public interface IFlyable
{
    void Fly();
}

public class Bird : Animal, IFlyable
{
    public override string MakeSound() => "Tweet";
    public void Fly() => Console.WriteLine("Flying");
}
